<input required name="name" value="{{ old('name',$category->name) }}" class="rounded-xl border-slate-300" placeholder="Category name"><input name="slug" value="{{ old('slug',$category->slug) }}" class="rounded-xl border-slate-300" placeholder="stable-slug"><select name="parent_id" class="rounded-xl border-slate-300"><option value="">Top-level category</option>@foreach($categories as $parent)<option value="{{ $parent->id }}" @selected(old('parent_id',$category->parent_id)===$parent->id) @disabled($category->exists&&$category->id===$parent->id)>{{ $parent->name }}</option>@endforeach</select><select required name="area" class="rounded-xl border-slate-300">@foreach($areas as $value=>$label)<option value="{{ $value }}" @selected(old('area',$category->area ?: 'academics_research')===$value)>{{ $label }}</option>@endforeach</select><input name="icon" maxlength="50" value="{{ old('icon',$category->icon) }}" class="rounded-xl border-slate-300" placeholder="Icon name"><input required type="number" min="0" max="10000" name="sort_order" value="{{ old('sort_order',$category->sort_order ?? 0) }}" class="rounded-xl border-slate-300" placeholder="Order"><textarea name="description" rows="2" maxlength="2000" class="rounded-xl border-slate-300 sm:col-span-2" placeholder="Description">{{ old('description',$category->description) }}</textarea><label class="sm:col-span-2 text-xs font-bold text-slate-500">Allowed types (empty means all)<select multiple name="allowed_publication_types[]" class="mt-2 h-36 w-full rounded-xl border-slate-300">@foreach($types as $type)<option value="{{ $type->id }}" @selected(in_array($type->id,old('allowed_publication_types',$category->allowed_publication_types??[])))>{{ $type->name }}</option>@endforeach</select></label><label class="flex gap-2 text-sm"><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$category->is_active ?? true)) class="rounded">Active</label>
